-- -----------------------------------
-- Table structure for `ip_camera_details`
-- -----------------------------------

DROP TABLE IF EXISTS `ip_camera_details`;
CREATE TABLE `ip_camera_details` (
  `id` int(10) NOT NULL,
  `ATMID` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `DVRIP` varchar(25) CHARACTER SET utf8 DEFAULT NULL,
  `cam1` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `port1` varchar(10) CHARACTER SET utf8 NOT NULL,
  `username1` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `password1` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `cam2` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `port2` varchar(4) CHARACTER SET utf8 DEFAULT NULL,
  `username2` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `password2` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `cam3` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `port3` varchar(4) CHARACTER SET utf8 DEFAULT NULL,
  `username3` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `password3` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `cam4` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `port4` varchar(2) CHARACTER SET utf8 DEFAULT NULL,
  `username4` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `password4` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

